 static void choose(Activity a,String id,String title){String[] names={"最高画質","1080p以下","720p以下","480p以下","360p以下"};int[] heights={0,1080,720,480,360};UiDialogs.show(UiDialogs.builder(PlaybackSession.dialogContext(a)).setTitle("MP4で保存").setItems(names,(d,n)->{if(prefs(a).getString(TREE,"").isEmpty())folder(a,id,title,heights[n]);else enqueue(a,id,title,heights[n]);}).setNegativeButton(android.R.string.cancel,null).create());}
