 public static void settings(PreferenceActivity a){Preference cache=a.findPreference("cache_dir");PreferenceGroup group=cache==null?null:parent(a.getPreferenceScreen(),cache);if(group==null)return;Preference p=a.findPreference(TREE);if(p==null){p=new Preference(a);p.setKey(TREE);p.setTitle("MP4の保存先フォルダ");p.setOrder(Integer.MAX_VALUE);group.addPreference(p);}String value=prefs(a).getString(TREE,"");String location="未指定（初回ダウンロード時に選択）";try{if(!value.isEmpty())location=DocumentsContract.getTreeDocumentId(Uri.parse(value));}catch(Exception ignored){}p.setSummary(location+"\n保存したMP4は本アプリでは再生できません。外部の動画再生アプリをご利用ください。");p.setOnPreferenceClickListener(v->{folder(a,null,null,0);return true;});}
