 public static final class FolderPicker extends android.app.Fragment{String id,title;int height;boolean picking;public FolderPicker(){}public void onCreate(Bundle b){super.onCreate(b);if(b!=null){id=b.getString("id");title=b.getString("title");height=b.getInt("height");picking=b.getBoolean("picking");}}public void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("id",id);b.putString("title",title);b.putInt("height",height);b.putBoolean("picking",picking);}void pick(String i,String t,int h){if(picking)return;id=i;title=t;height=h;picking=true;Intent request=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);String previous=prefs(getActivity()).getString(TREE,"");if(!previous.isEmpty()&&Build.VERSION.SDK_INT>=26)request.putExtra(DocumentsContract.EXTRA_INITIAL_URI,Uri.parse(previous));try{startActivityForResult(request,115);}catch(Exception e){picking=false;Toast.makeText(getActivity(),"フォルダ選択画面を開けませんでした",1).show();}}public void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=115)return;picking=false;Activity a=getActivity();if(a==null||result!=Activity.RESULT_OK||data==null||data.getData()==null){id=null;return;}try{Uri tree=data.getData();int flags=data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);if((flags&Intent.FLAG_GRANT_WRITE_URI_PERMISSION)==0)throw new IOException();a.getContentResolver().takePersistableUriPermission(tree,flags);Uri probe=DocumentsContract.createDocument(a.getContentResolver(),DownloadJobs115.document(tree),"application/octet-stream",".nicoid-write-test-"+UUID.randomUUID());if(probe==null)throw new IOException();DocumentsContract.deleteDocument(a.getContentResolver(),probe);if(!prefs(a).edit().putString(TREE,tree.toString()).commit())throw new IOException();if(a instanceof PreferenceActivity)settings((PreferenceActivity)a);if(id!=null)enqueue(a,id,title,height);}catch(Exception e){Toast.makeText(a,"このフォルダには保存できません。別のフォルダを指定してください",1).show();}finally{id=null;}}}
 static final class Row{String title,detail,status,id,uri;long bytes,total;int percent=-1;DownloadJobs115.Job job;boolean cache;}
 static List<Row> caches(Context c){List<Row> rows=new ArrayList<>();try{CacheFolders.init(c);String root=CacheFolders.root(c)+"/nicoid/nicoid_cache/";File[] files=new CacheFile(root).listFiles();if(files!=null)for(File f:files){if(!f.getName().endsWith(".json"))continue;String id=CacheFolders.videoId(f.getName());if(id==null)continue;long bytes=CachedPlayback.completedBytes(root,id);if(bytes<=0)continue;Row r=new Row();r.id=id;r.title=id;r.cache=true;r.status="保存済み";r.bytes=bytes;r.percent=100;try(InputStream in=new CacheInputStream(f);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>2*1024*1024)throw new IOException();out.write(b,0,n);}r.title=CacheTitles117.title(new JSONObject(out.toString("UTF-8")),id);CacheTitles117.remember(id,r.title);}rows.add(r);}}catch(Exception e){android.util.Log.w("nicoid-download","Cannot list cached downloads",e);}return rows;}
 static Row liveCache(){try{Class<?> c=Class.forName("com.sauzask.nicoid.NicoidDownloadCache");if(!c.getField("v").getBoolean(null)||DownloadWorker115.active!=null)return null;Row r=new Row();r.cache=true;r.id=String.valueOf(c.getField("t").get(null));if(!r.id.matches("(?:sm|so|nm|ss)?[0-9]+"))return null;r.title=CacheTitles117.known(r.id);r.status="ダウンロード中";r.bytes=c.getField("s").getLong(null);r.total=c.getField("r").getLong(null);r.percent=r.total>0?(int)Math.min(99,r.bytes*100d/r.total):-1;return r;}catch(Exception ignored){return null;}}
 static List<Row> queuedCaches(){List<Row> out=new ArrayList<>();try{Object queue=Class.forName("com.sauzask.nicoid.NicoidDownloadCache").getField("u").get(null);if(queue instanceof List)for(Object value:new ArrayList<>((List<?>)queue))if(value instanceof Intent&&!((Intent)value).hasExtra("nicoid_mp4_job115")){Intent i=(Intent)value;Row r=new Row();r.cache=true;r.id=i.getStringExtra("id");r.title=i.getStringExtra("title");if(r.title==null||r.title.isEmpty())r.title=CacheTitles117.known(r.id);else CacheTitles117.remember(r.id,r.title);r.status="キュー待ち";out.add(r);}}catch(Exception ignored){}return out;}
