 static final class Manager extends BaseAdapter{final WeakReference<Activity> activity;final Context context;final ListView list;final ArrayList<Row> rows=new ArrayList<>();List<Row> cacheRows=new ArrayList<>();AlertDialog dialog;Ui110.Tabs tabs;long lastScan;int mode;boolean closed,scanning;String cacheActive="";Manager(Activity a,Context c,ListView l){activity=new WeakReference<>(a);context=c;list=l;}final Runnable tick=new Runnable(){public void run(){if(closed)return;update();if(mode==1&&SystemClock.elapsedRealtime()-lastScan>=5000)reload();MAIN.postDelayed(this,1000);}};void reload(){if(scanning||closed)return;scanning=true;lastScan=SystemClock.elapsedRealtime();Context app=context.getApplicationContext();new Thread(()->{DownloadFiles118.reconcile(app);List<Row> saved=caches(app);MAIN.post(()->{scanning=false;if(!closed){cacheRows=saved;update();}});},"nicoid-download-list").start();}void update(){Row live=liveCache();String id=live==null?"":live.id;if(!cacheActive.equals(id)){boolean had=!cacheActive.isEmpty();cacheActive=id;if(had)reload();}rows.clear();for(DownloadJobs115.Job j:DownloadJobs115.all()){boolean saved="保存済み".equals(j.phase),error="エラー".equals(j.phase)||"キャンセル".equals(j.phase);if(mode==1?!saved:mode==2?!error:saved||error)continue;Row r=new Row();r.job=j;r.id=j.id;r.title=j.title;r.detail=j.quality;r.status=j.phase;r.bytes=j.bytes;r.total=j.total;r.percent=j.percent();r.uri=j.uri;rows.add(r);}if(mode==1)rows.addAll(cacheRows);if(mode==0){if(live!=null)rows.add(live);rows.addAll(queuedCaches());}notifyDataSetChanged();}public int getCount(){return rows.size();}public Object getItem(int i){return rows.get(i);}public long getItemId(int i){return i;}public View getView(int n,View old,ViewGroup parent){LinearLayout row=old instanceof LinearLayout?(LinearLayout)old:PanelUi.column(context);if(old==null){int pad=PanelUi.dp(context,12);row.setPadding(pad,pad,pad,pad);row.addView(PanelUi.text(context,"",16));row.addView(PanelUi.text(context,"",12));ProgressBar p=new ProgressBar(context,null,android.R.attr.progressBarStyleHorizontal);p.setProgressTintList(ColorStateList.valueOf(UiDialogs.accent(context)));p.setIndeterminateTintList(ColorStateList.valueOf(UiDialogs.accent(context)));row.addView(p,new LinearLayout.LayoutParams(-1,PanelUi.dp(context,6)));row.addView(PanelUi.text(context,"",12));}Row r=rows.get(n);((TextView)row.getChildAt(0)).setText(r.title);((TextView)row.getChildAt(1)).setText((r.cache?"キャッシュ":"MP4")+" · "+r.status+(r.detail==null||r.detail.isEmpty()?"":" · "+r.detail));ProgressBar p=(ProgressBar)row.getChildAt(2);p.setVisibility(mode==0&&!"キュー待ち".equals(r.status)&&!"一時停止".equals(r.status)?View.VISIBLE:View.GONE);p.setIndeterminate(r.percent<0);p.setProgress(Math.max(0,r.percent));String amount=DownloadJobs115.format(r.bytes)+(r.total>0?" / "+DownloadJobs115.format(r.total):"")+(r.percent>=0&&mode==0?" · "+r.percent+"%":"");if(r.job!=null&&"ダウンロード中".equals(r.status)&&r.job.started>0){long elapsed=SystemClock.elapsedRealtime()-r.job.started;if(elapsed>1000){double speed=r.bytes/(elapsed/1000d);amount+=" · "+DownloadJobs115.format((long)speed)+"/秒";if(r.total>r.bytes&&speed>0)amount+=" · 残り約"+(long)((r.total-r.bytes)/speed)+"秒";}}if("キュー待ち".equals(r.status))amount="容量は取得開始後に表示します";if(r.job!=null&&!r.job.error.isEmpty())amount+="\n"+r.job.error;((TextView)row.getChildAt(3)).setText(amount);return row;}
 boolean removeHistory(Row r){if(r.job==null||!("エラー".equals(r.job.phase)||"キャンセル".equals(r.job.phase)))return false;Activity a=activity.get();if(a==null||a.isDestroyed())return true;UiDialogs.show(UiDialogs.builder(context).setTitle("履歴から削除しますか？").setMessage(r.title).setPositiveButton("削除",(d,n)->{DownloadFiles118.forget(a,r.job);update();}).setNegativeButton(android.R.string.cancel,null).create());return true;}
 void actions(Row r){Activity a=activity.get();if(a==null||a.isDestroyed())return;if(r.cache){if("保存済み".equals(r.status))CacheFolders.startActivity(a,new Intent().setClassName(a,"com.sauzask.nicoid.NicoidCacheManagerActivity"));else Toast.makeText(a,"キャッシュの操作は既存のキャッシュリストで行えます",0).show();return;}DownloadJobs115.Job j=r.job;ArrayList<String> labels=new ArrayList<>();ArrayList<Runnable> actions=new ArrayList<>();if("保存済み".equals(j.phase)){labels.add("外部アプリで開く");actions.add(()->open(a,j,false));labels.add("共有");actions.add(()->open(a,j,true));labels.add("保存先を表示");actions.add(()->UiDialogs.show(UiDialogs.builder(context).setTitle("保存先").setMessage(DocumentsContract.getTreeDocumentId(Uri.parse(j.tree))).setPositiveButton(android.R.string.ok,null).create()));labels.add("削除");actions.add(()->UiDialogs.show(UiDialogs.builder(context).setTitle("MP4を削除しますか？").setMessage(j.title).setPositiveButton("削除",(d,n)->new Thread(()->{try{if(!DocumentsContract.deleteDocument(a.getContentResolver(),Uri.parse(j.uri)))throw new IOException();synchronized(DownloadJobs115.class){DownloadJobs115.jobs.remove(j);DownloadJobs115.changed(a);}}catch(Exception e){MAIN.post(()->Toast.makeText(a,"削除できませんでした",1).show());}MAIN.post(this::update);}).start()).setNegativeButton(android.R.string.cancel,null).create()));}else if(Arrays.asList("一時停止","エラー","キャンセル").contains(j.phase)){labels.add("再取得");actions.add(()->{j.tree=prefs(a).getString(TREE,"");if(j.tree.isEmpty())folder(a,j.id,j.title,j.height);else DownloadJobs115.submit(a,j);update();});if("エラー".equals(j.phase)||"キャンセル".equals(j.phase)){labels.add("履歴から削除");actions.add(()->removeHistory(r));}}else{labels.add("一時停止（再開時は再取得）");actions.add(()->{DownloadJobs115.control(j,true);update();});labels.add("キャンセル");actions.add(()->{DownloadJobs115.control(j,false);update();});}UiDialogs.show(UiDialogs.builder(context).setTitle(j.title).setItems(labels.toArray(new String[0]),(d,n)->actions.get(n).run()).setNegativeButton(android.R.string.cancel,null).create());}
 }
 static void open(Activity a,DownloadJobs115.Job j,boolean share){try{Intent i=share?new Intent(Intent.ACTION_SEND).setType("video/mp4").putExtra(Intent.EXTRA_STREAM,Uri.parse(j.uri)):new Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse(j.uri),"video/mp4");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newRawUri(j.title,Uri.parse(j.uri)));ArrayList<Intent> targets=new ArrayList<>();for(android.content.pm.ResolveInfo resolved:a.getPackageManager().queryIntentActivities(i,android.content.pm.PackageManager.MATCH_DEFAULT_ONLY)){if(resolved.activityInfo==null||a.getPackageName().equals(resolved.activityInfo.packageName))continue;targets.add(new Intent(i).setComponent(new ComponentName(resolved.activityInfo.packageName,resolved.activityInfo.name)));}if(targets.isEmpty())throw new ActivityNotFoundException();Intent chooser=Intent.createChooser(targets.remove(0),share?"MP4を共有":"外部アプリで開く");chooser.putExtra(Intent.EXTRA_INITIAL_INTENTS,targets.toArray(new Intent[0]));a.startActivity(chooser);}catch(Exception e){Toast.makeText(a,"対応する外部アプリを開けませんでした",1).show();}}
